package com.petlis.service.impl;
import com.petlis.common.exception.BusinessException;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.context.annotation.Import;import org.springframework.transaction.annotation.Transactional;import java.io.ByteArrayInputStream;import java.math.BigDecimal;import java.util.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.apache.poi.ss.usermodel.CellType;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@SpringBootTest @Import(LegacyBankJdbcTestConfiguration.class) @Transactional("legacyBankTestTransactions") @EnabledIfEnvironmentVariable(named="PETLIS_LOCAL_DB_TEST",matches="true") class LegacyOrderExportLocalDatabaseTest {
 @Autowired FeatureStore store;LegacyMainOrderLocalDatabaseTest f;LegacyOrderExportService service;LegacyOrderDetailService details;int test;long group;
 @BeforeEach void setup(){f=new LegacyMainOrderLocalDatabaseTest();f.store=store;f.setup();group=900000000L+f.actor;f.mapListAdmin(String.valueOf(group),"normal");store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET CreateDataTypeIId=?,SampleStatus=2,UserNO='000001234567890123456789',ChipNO='=SUM(1,2)',DoctorName='合成医师' WHERE ListDiagnosisProjectId=?",group,f.order);store.jdbc().update("INSERT INTO lin_operational_config(config_key,config_value,description,updated_by) VALUES('legacy-order-export','{\"enabled\":true}','transaction-only export fixture',?) ON DUPLICATE KEY UPDATE config_value=VALUES(config_value),status='ACTIVE'",f.actor);store.jdbc().update("INSERT INTO lin_operational_config(config_key,config_value,description,updated_by) VALUES('legacy-order-details','{\"enabled\":true,\"writeEnabled\":true}','transaction-only export detail fixture',?) ON DUPLICATE KEY UPDATE config_value=VALUES(config_value),status='ACTIVE'",f.actor);test=LegacyDetailFixtures.test(store,"it_export_"+f.actor);details=new LegacyOrderDetailService(store,f.access,new LegacyReportLinks("",""));service=new LegacyOrderExportService(store,f.access,f.service);}
 long detail(long order,String price,int paid,int exempt){return details.create(order,new LegacyOrderDetailService.CreateCommand(test,new BigDecimal(price),"10",new BigDecimal(price),"export",0,"",0,exempt,paid,0,"mail","report",f.key()));}
 @Test void exportKeepsOriginalColumnsContentAndOnlyVisibleRows()throws Exception{long own=detail(f.order,"12.50",2,0);long foreign=LegacyDetailFixtures.order(store,"it_export_foreign_"+f.actor,f.actor),hidden=LegacyDetailFixtures.order(store,"it_export_hidden_"+f.actor,f.actor);detail(foreign,"99.00",0,0);detail(hidden,"88.00",0,0);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET CreateDataTypeIId=?,SampleStatus=2 WHERE ListDiagnosisProjectId=?",group+1,foreign);store.jdbc().update("UPDATE lin_lb_listdiagnosisproject SET CreateDataTypeIId=?,SampleStatus=-1 WHERE ListDiagnosisProjectId=?",group,hidden);var before=store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.order);try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(service.export(null)))){var sheet=workbook.getSheetAt(0);assertEquals(1,sheet.getLastRowNum());assertEquals(28,sheet.getRow(0).getLastCellNum());for(int i=0;i<28;i++)assertEquals(LegacyOrderExportWorkbook.HEADERS.get(i),sheet.getRow(0).getCell(i).getStringCellValue());var row=sheet.getRow(1);assertEquals(String.valueOf(own),row.getCell(1).getStringCellValue());assertEquals("000001234567890123456789",row.getCell(2).getStringCellValue());assertEquals("=SUM(1,2)",row.getCell(5).getStringCellValue());assertEquals(CellType.STRING,row.getCell(5).getCellType());assertEquals("12.50",row.getCell(23).getStringCellValue());assertEquals("转账",row.getCell(24).getStringCellValue());assertEquals("2",row.getCell(25).getStringCellValue());assertEquals("合成医师",row.getCell(27).getStringCellValue());assertEquals("1",workbook.getSheet("导出说明").getRow(1).getCell(1).getStringCellValue());}assertEquals(before,store.one("SELECT * FROM lin_lb_listdiagnosisproject WHERE ListDiagnosisProjectId=?",f.order));try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(service.export(4)))){assertEquals(0,workbook.getSheetAt(0).getLastRowNum());}}
 @Test void newestDetailFirstAndExemptLabelAndRawDateRemain()throws Exception{detail(f.order,"7.25",4,0);long last=detail(f.order,"99.00",0,1);try(var workbook=new XSSFWorkbook(new ByteArrayInputStream(service.export(2)))){var row=workbook.getSheetAt(0).getRow(1);assertEquals(String.valueOf(last),row.getCell(1).getStringCellValue());assertEquals("免除",row.getCell(24).getStringCellValue());assertEquals("2024-05-06 00:00:00",row.getCell(11).getStringCellValue());assertEquals("-",row.getCell(20).getStringCellValue());}}
 @Test void gatesMappingAndRoleNeverFallBackToWholeDatabase(){detail(f.order,"1.00",0,0);store.jdbc().update("UPDATE lin_operational_config SET config_value='{\"enabled\":\"true\"}' WHERE config_key='legacy-order-export'");assertEquals(409,assertThrows(BusinessException.class,()->service.export(null)).getCode());store.jdbc().update("UPDATE lin_operational_config SET config_value='{\"enabled\":true}' WHERE config_key='legacy-order-export'");store.jdbc().update("UPDATE lin_admin SET datagroup='1,2 OR 1=1' WHERE username=?","it_scope_"+f.actor);assertEquals(409,assertThrows(BusinessException.class,()->service.export(null)).getCode());doThrow(new BusinessException(403,"denied")).when(f.access).requireAdmin();assertEquals(403,assertThrows(BusinessException.class,()->service.export(null)).getCode());}
}
